/* Leonida Legends — GTA VI trophy tracker. Original CSS, no artwork, no network. */
:root {
  --bg: #140a1e;
  --panel: rgba(28, 16, 46, 0.92);
  --panel-line: rgba(255, 138, 196, 0.22);
  --pink: #ff5fa8;
  --pink-soft: #ff9ec7;
  --purple: #8a5cf6;
  --teal: #2ee6c8;
  --amber: #ffcf5c;
  --text: #f3e9fb;
  --muted: #b9a8cf;
  --bronze: #cd7f42;
  --silver: #c9cbd6;
  --gold: #ffd24a;
  --platinum: #eef2ff;
  --radius: 14px;
  --shadow: 0 10px 34px rgba(0, 0, 0, 0.45);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: "Segoe UI", "Helvetica Neue", Arial, "Noto Sans", sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  line-height: 1.45;
}

/* Fixed sunset backdrop: pink → purple → teal, sun glow, no images. */
.sunset {
  position: fixed;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(circle at 78% 8%, rgba(255, 207, 92, 0.28), transparent 26%),
    radial-gradient(ellipse 70% 46% at 82% 0%, rgba(255, 95, 168, 0.38), transparent 62%),
    linear-gradient(168deg, #2b1244 0%, #1b0f2e 34%, #0f1f33 72%, #0c2630 100%);
}
.sunset::after {
  content: "";
  position: absolute;
  inset: auto 6% 0 6%;
  bottom: 0;
  height: 30%;
  background: repeating-linear-gradient(
    0deg,
    rgba(46, 230, 200, 0.10) 0 2px,
    transparent 2px 9px
  );
  -webkit-mask-image: linear-gradient(to top, black, transparent);
  mask-image: linear-gradient(to top, black, transparent);
}

header {
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
  align-items: center;
  justify-content: space-between;
  padding: 30px 40px 18px;
  border-bottom: 1px solid var(--panel-line);
}
.brand h1 {
  margin: 0;
  font-size: 2.3rem;
  letter-spacing: 0.04em;
  font-weight: 800;
  background: linear-gradient(92deg, var(--pink), var(--purple) 48%, var(--teal));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 0 34px rgba(255, 95, 168, 0.22);
}
.tagline {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 0.92rem;
  letter-spacing: 0.02em;
}
.progress-wrap {
  min-width: 320px;
  flex: 1 1 340px;
  max-width: 520px;
  background: var(--panel);
  border: 1px solid var(--panel-line);
  border-radius: var(--radius);
  padding: 14px 18px;
  box-shadow: var(--shadow);
}
.progress-num {
  font-size: 1.12rem;
  font-weight: 700;
  color: var(--pink-soft);
  margin-bottom: 8px;
}
.progress-bar {
  height: 12px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.38);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.07);
}
.progress-fill {
  height: 100%;
  width: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--teal), var(--purple) 55%, var(--pink));
  box-shadow: 0 0 14px rgba(255, 95, 168, 0.55);
  transition: width 0.35s ease;
}
.grade-tally {
  margin-top: 9px;
  font-size: 0.8rem;
  color: var(--muted);
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.grade-tally b { color: var(--text); font-weight: 600; }

/* Controls */
.controls {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: flex-end;
  padding: 12px 40px;
  background: rgba(16, 9, 28, 0.94);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--panel-line);
}
.field { display: flex; flex-direction: column; gap: 4px; }
.field-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--teal);
  font-weight: 700;
}
.field input, .field select {
  background: #241436;
  color: var(--text);
  border: 1px solid var(--panel-line);
  border-radius: 9px;
  padding: 8px 11px;
  font-size: 0.92rem;
  outline: none;
}
.field input:focus, .field select:focus { border-color: var(--pink); box-shadow: 0 0 0 2px rgba(255, 95, 168, 0.25); }
.search-field { min-width: 230px; flex: 1 1 240px; }
.toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.85rem;
  color: var(--muted);
  cursor: pointer;
  padding: 8px 4px;
}
.toggle input { accent-color: var(--pink); width: 16px; height: 16px; }
.toggle b { color: var(--amber); font-weight: 600; }
.actions { display: flex; gap: 10px; flex-wrap: wrap; margin-left: auto; }
.btn {
  border: 1px solid var(--panel-line);
  background: #2a1742;
  color: var(--text);
  border-radius: 9px;
  padding: 9px 14px;
  font-size: 0.88rem;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
}
.btn:hover { background: #37205a; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(138, 92, 246, 0.3); }
.btn-accent {
  background: linear-gradient(92deg, var(--pink), var(--purple));
  border: none;
  font-weight: 700;
}
.btn-accent:hover { box-shadow: 0 4px 20px rgba(255, 95, 168, 0.5); }
.btn-ghost { background: transparent; }
.import-btn { position: relative; overflow: hidden; display: inline-flex; align-items: center; }
.import-btn input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }

main { padding: 22px 40px 60px; }

/* Trophy board */
.board {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 14px;
}
.card {
  position: relative;
  background: var(--panel);
  border: 1px solid var(--panel-line);
  border-radius: var(--radius);
  padding: 14px 16px 12px;
  box-shadow: var(--shadow);
  cursor: pointer;
  transition: transform 0.13s ease, border-color 0.13s ease, box-shadow 0.13s ease;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.card:hover { transform: translateY(-2px); border-color: var(--pink); box-shadow: 0 12px 30px rgba(255, 95, 168, 0.18); }
.card.earned { border-color: rgba(46, 230, 200, 0.55); }
.card.earned::after {
  content: "✓ earned";
  position: absolute;
  top: 10px;
  right: 12px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--teal);
  letter-spacing: 0.06em;
}
.card-head {
  display: flex;
  align-items: center;
  gap: 10px;
}
.grade-badge {
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  border: 2px solid rgba(255, 255, 255, 0.25);
}
.grade-badge.platinum { background: linear-gradient(135deg, #fff, #b9c2e8); color: #2a2350; }
.grade-badge.gold { background: linear-gradient(135deg, #ffe89a, #f0a92e); color: #3a2503; }
.grade-badge.silver { background: linear-gradient(135deg, #f2f4fa, #9ea3b5); color: #262833; }
.grade-badge.bronze { background: linear-gradient(135deg, #e8a86a, #a35c28); color: #2e1703; }
.card-title { margin: 0; font-size: 1.02rem; font-weight: 700; line-height: 1.25; }
.card-desc { margin: 0; font-size: 0.85rem; color: var(--muted); }
.card-tags { display: flex; gap: 7px; flex-wrap: wrap; margin-top: auto; }
.tag {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: var(--muted);
}
.tag.kind-story { color: var(--pink-soft); border-color: rgba(255, 95, 168, 0.4); }
.tag.kind-activity { color: var(--teal); border-color: rgba(46, 230, 200, 0.4); }
.tag.kind-collectible { color: var(--purple); border-color: rgba(138, 92, 246, 0.5); }
.tag.kind-crime { color: var(--amber); border-color: rgba(255, 207, 92, 0.4); }
.tag.kind-economy { color: #9ef0a0; border-color: rgba(120, 230, 130, 0.35); }
.tag.kind-special { color: #c9b8ff; border-color: rgba(201, 184, 255, 0.4); }
.tag.kind-completion { color: #fff; border-color: rgba(255, 255, 255, 0.45); }
.tag.missable { color: #ff8f6b; border-color: rgba(255, 143, 107, 0.55); background: rgba(255, 143, 107, 0.08); }
.tag.count { color: var(--text); border-color: rgba(255, 255, 255, 0.18); }
.card-peek { font-size: 0.78rem; color: var(--muted); margin: 0; }
.card-peek em { color: var(--teal); font-style: normal; }

/* Spoiler-blurred story cards */
.card.spoiler .card-title, .card.spoiler .card-desc, .card.spoiler .card-peek {
  filter: blur(7px);
  pointer-events: none;
  user-select: none;
}
.spoiler-hint {
  font-size: 0.72rem;
  color: var(--amber);
  letter-spacing: 0.04em;
}

/* Detail drawer */
.detail {
  position: fixed;
  top: 0;
  right: 0;
  width: min(560px, 94vw);
  height: 100vh;
  overflow-y: auto;
  background: rgba(20, 11, 32, 0.985);
  border-left: 1px solid var(--panel-line);
  box-shadow: -18px 0 50px rgba(0, 0, 0, 0.6);
  z-index: 60;
  padding: 26px 30px 60px;
}
.detail-close { float: right; }
.detail h2 {
  margin: 6px 0 2px;
  font-size: 1.7rem;
  background: linear-gradient(92deg, var(--pink), var(--purple) 60%, var(--teal));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.detail .detail-desc {
  color: var(--muted);
  font-style: italic;
  margin: 4px 0 14px;
}
.detail .meta-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
.detail h3 {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--teal);
  margin: 20px 0 6px;
}
.detail .guide-text { font-size: 0.96rem; line-height: 1.6; }
.detail .sources {
  margin: 10px 0 0;
  padding: 12px 14px;
  background: rgba(46, 230, 200, 0.06);
  border: 1px solid rgba(46, 230, 200, 0.22);
  border-radius: 10px;
}
.detail .sources ul { margin: 6px 0 0; padding-left: 18px; }
.detail .sources li { font-size: 0.85rem; color: var(--muted); margin-bottom: 3px; }
.detail .sources li::marker { color: var(--teal); }
.detail .warn {
  margin-top: 14px;
  padding: 11px 14px;
  border-radius: 10px;
  background: rgba(255, 143, 107, 0.1);
  border: 1px solid rgba(255, 143, 107, 0.45);
  color: #ffb59c;
  font-size: 0.88rem;
}
.detail .earn-row {
  display: flex;
  gap: 12px;
  align-items: center;
  margin: 18px 0 4px;
}
.detail .earn-row label { display: flex; gap: 8px; align-items: center; cursor: pointer; font-size: 0.95rem; }
.detail .earn-row input { width: 18px; height: 18px; accent-color: var(--teal); }

/* Roadmap */
.roadmap {
  position: fixed;
  inset: 0;
  overflow-y: auto;
  z-index: 55;
  background: rgba(16, 9, 28, 0.985);
  padding: 26px 40px 60px;
}
.roadmap h2 { margin: 4px 0 6px; font-size: 1.55rem; }
.roadmap-note { color: var(--muted); font-size: 0.9rem; max-width: 70ch; }
.roadmap ol { list-style: none; padding: 0; margin: 18px 0 0; counter-reset: stage; }
.roadmap li {
  counter-increment: stage;
  position: relative;
  padding: 14px 16px 14px 58px;
  margin-bottom: 12px;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 12px;
}
.roadmap li::before {
  content: counter(stage);
  position: absolute;
  left: 14px;
  top: 14px;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  background: linear-gradient(135deg, var(--pink), var(--purple));
  color: #fff;
}
.roadmap h3 { margin: 0 0 4px; font-size: 1.05rem; color: var(--pink-soft); }
.roadmap .stage-why { margin: 0 0 8px; font-size: 0.86rem; color: var(--muted); }
.roadmap .stage-trophies { display: flex; gap: 7px; flex-wrap: wrap; }
.roadmap .chip {
  font-size: 0.74rem;
  padding: 3px 9px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: var(--text);
  cursor: pointer;
  background: rgba(255, 255, 255, 0.04);
}
.roadmap .chip:hover { border-color: var(--teal); color: var(--teal); }
.roadmap .chip.done { text-decoration: line-through; opacity: 0.55; }
.roadmap .chip.miss { color: #ff8f6b; border-color: rgba(255, 143, 107, 0.5); }

.empty {
  text-align: center;
  color: var(--muted);
  font-size: 1.05rem;
  padding: 60px 0;
}

footer {
  border-top: 1px solid var(--panel-line);
  padding: 22px 40px 40px;
  color: var(--muted);
  font-size: 0.8rem;
}
.neon { color: var(--teal); text-shadow: 0 0 12px rgba(46, 230, 200, 0.5); }

@media (max-width: 760px) {
  header, .controls, main, footer { padding-left: 18px; padding-right: 18px; }
  .brand h1 { font-size: 1.7rem; }
  .board { grid-template-columns: 1fr; }
}
